(() => {
'use strict';

const APP_KEY='myfit-ai-github-v1';
const el=id=>document.getElementById(id);
const esc=v=>String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const FOODS=[
{name:'Moong Dal Chilla',diet:['vegetarian','vegan','jain'],meal:['breakfast'],cuisine:['north-indian','pan-indian'],prep:20,budget:'low',tags:['protein','fibre'],portion:'2 medium chillas + vegetable filling'},
{name:'Masala Oats with Vegetables',diet:['vegetarian','vegan','jain'],meal:['breakfast'],cuisine:['pan-indian','south-indian'],prep:15,budget:'low',tags:['fibre','quick'],portion:'1 bowl cooked oats with mixed vegetables'},
{name:'Egg Bhurji with Multigrain Roti',diet:['eggetarian','non-vegetarian'],meal:['breakfast'],cuisine:['north-indian'],prep:15,budget:'low',tags:['protein','quick'],portion:'2 eggs + 2 small rotis + vegetables'},
{name:'Paneer Bhurji with Multigrain Roti',diet:['vegetarian','jain'],meal:['breakfast','dinner'],cuisine:['north-indian'],prep:20,budget:'medium',tags:['protein'],portion:'100 g paneer + 2 small rotis'},
{name:'Idli with Sambar',diet:['vegetarian','vegan'],meal:['breakfast'],cuisine:['south-indian'],prep:10,budget:'low',tags:['balanced','quick'],portion:'3 idlis + 1 bowl sambar'},
{name:'Vegetable Poha with Peanuts',diet:['vegetarian','vegan','jain'],meal:['breakfast'],cuisine:['west-indian'],prep:15,budget:'low',tags:['balanced','quick'],portion:'1.5 cups poha with vegetables and peanuts'},
{name:'Grilled Chicken, Roti & Salad',diet:['non-vegetarian'],meal:['lunch','dinner'],cuisine:['north-indian','pan-indian'],prep:30,budget:'medium',tags:['protein'],portion:'120 g chicken + 2 small rotis + salad'},
{name:'Fish Curry, Rice & Vegetables',diet:['non-vegetarian'],meal:['lunch','dinner'],cuisine:['south-indian','west-indian'],prep:35,budget:'medium',tags:['protein','balanced'],portion:'120 g fish + 1 cup cooked rice + vegetables'},
{name:'Rajma with Brown Rice & Salad',diet:['vegetarian','vegan'],meal:['lunch','dinner'],cuisine:['north-indian'],prep:45,budget:'low',tags:['fibre','balanced'],portion:'1 cup rajma + 1 cup brown rice + salad'},
{name:'Dal Tadka, Roti & Cucumber',diet:['vegetarian','vegan','jain'],meal:['lunch','dinner'],cuisine:['north-indian','pan-indian'],prep:30,budget:'low',tags:['balanced','fibre'],portion:'1.25 cups dal + 2 small rotis + cucumber'},
{name:'Tofu Stir-Fry with Rice',diet:['vegan'],meal:['lunch','dinner'],cuisine:['pan-indian'],prep:20,budget:'medium',tags:['protein','quick'],portion:'150 g tofu + 1 cup rice + mixed vegetables'},
{name:'Chole with Roti & Salad',diet:['vegetarian','vegan'],meal:['lunch','dinner'],cuisine:['north-indian'],prep:35,budget:'low',tags:['fibre','balanced'],portion:'1 cup chole + 2 small rotis + salad'},
{name:'Jain Moong Dal Khichdi',diet:['jain'],meal:['lunch','dinner'],cuisine:['north-indian'],prep:30,budget:'low',tags:['balanced'],portion:'1.5 cups moong khichdi prepared without onion/garlic/root vegetables'},
{name:'Greek Yogurt with Fruit & Nuts',diet:['vegetarian'],meal:['snack','breakfast'],cuisine:['pan-indian'],prep:5,budget:'medium',tags:['protein','quick'],portion:'200 g plain yogurt + 1 fruit + small nut portion'},
{name:'Boiled Eggs with Fruit',diet:['eggetarian','non-vegetarian'],meal:['snack','breakfast'],cuisine:['pan-indian'],prep:10,budget:'low',tags:['protein','quick'],portion:'2 eggs + 1 fruit'},
{name:'Roasted Chana with Buttermilk',diet:['vegetarian'],meal:['snack'],cuisine:['pan-indian'],prep:5,budget:'low',tags:['protein','quick'],portion:'40 g roasted chana + 250 ml buttermilk'},
{name:'Peanut Chaat',diet:['vegetarian','vegan','jain'],meal:['snack'],cuisine:['west-indian'],prep:10,budget:'low',tags:['balanced','quick'],portion:'40 g peanuts + cucumber + tomato + lemon'},
{name:'Fruit with Nuts',diet:['vegetarian','vegan','jain'],meal:['snack'],cuisine:['pan-indian'],prep:2,budget:'medium',tags:['quick'],portion:'1 fruit + 15 g nuts'}
];
const EXERCISES=[
{name:'Goblet Squat',mode:['gym','home'],goal:['muscle','fitness','fatloss'],level:['beginner','intermediate','advanced'],pattern:'legs',sets:3,reps:'8–12',rest:90,alt:'Bodyweight Squat'},
{name:'Bodyweight Squat',mode:['gym','home'],goal:['muscle','fitness','fatloss'],level:['beginner','intermediate','advanced'],pattern:'legs',sets:3,reps:'10–15',rest:60,alt:'Goblet Squat'},
{name:'Push-Up',mode:['gym','home'],goal:['muscle','fitness','fatloss'],level:['beginner','intermediate','advanced'],pattern:'push',sets:3,reps:'8–15',rest:75,alt:'Incline Push-Up'},
{name:'Incline Push-Up',mode:['gym','home'],goal:['muscle','fitness','fatloss'],level:['beginner'],pattern:'push',sets:3,reps:'8–12',rest:60,alt:'Push-Up'},
{name:'Dumbbell Row',mode:['gym','home'],goal:['muscle','fitness'],level:['beginner','intermediate','advanced'],pattern:'pull',sets:3,reps:'8–12/side',rest:90,alt:'Cable Row'},
{name:'Lat Pulldown',mode:['gym'],goal:['muscle','fitness'],level:['beginner','intermediate','advanced'],pattern:'pull',sets:3,reps:'8–12',rest:120,alt:'Dumbbell Row'},
{name:'Leg Press',mode:['gym'],goal:['muscle','fitness','fatloss'],level:['beginner','intermediate','advanced'],pattern:'legs',sets:3,reps:'8–12',rest:120,alt:'Goblet Squat'},
{name:'Romanian Deadlift',mode:['gym','home'],goal:['muscle','fitness'],level:['intermediate','advanced'],pattern:'hinge',sets:3,reps:'8–10',rest:120,alt:'Glute Bridge'},
{name:'Glute Bridge',mode:['gym','home'],goal:['fitness','fatloss','muscle'],level:['beginner','intermediate'],pattern:'hinge',sets:3,reps:'12–15',rest:60,alt:'Hip Thrust'},
{name:'Plank',mode:['gym','home'],goal:['fitness','fatloss','muscle'],level:['beginner','intermediate','advanced'],pattern:'core',sets:3,reps:'30–45 sec',rest:45,alt:'Dead Bug'},
{name:'Dead Bug',mode:['gym','home'],goal:['fitness','fatloss','muscle'],level:['beginner','intermediate'],pattern:'core',sets:3,reps:'6–10/side',rest:45,alt:'Plank'},
{name:'Brisk Walk',mode:['home','gym'],goal:['fatloss','fitness'],level:['beginner','intermediate','advanced'],pattern:'cardio',sets:1,reps:'15–40 min',rest:0,alt:'Stair Walking'},
{name:'Stair Walking',mode:['home','gym'],goal:['fatloss','fitness'],level:['beginner','intermediate'],pattern:'cardio',sets:1,reps:'8–15 min',rest:0,alt:'Brisk Walk'},
{name:'Incline Walk',mode:['gym'],goal:['fatloss','fitness'],level:['beginner','intermediate','advanced'],pattern:'cardio',sets:1,reps:'15–25 min',rest:0,alt:'Brisk Walk'},
{name:'Mobility Flow',mode:['home','gym'],goal:['fitness','fatloss','muscle'],level:['beginner','intermediate','advanced'],pattern:'mobility',sets:1,reps:'5–10 min',rest:0,alt:'Easy stretching'}
];

const DEMO={name:'Demo User',age:34,sex:'Male',height:175,weight:82,target:75,targetDate:'2026-11-21',diet:'non-vegetarian',gym:true,days:5,minutes:90,goal:'muscle',level:'intermediate',activity:'moderate',cuisine:'north-indian',meals:4,cooking:'moderate',budget:'medium',eatingOut:'sometimes',workoutTiming:'post',allergies:'',dislikes:'',steps:7000,sleep:7,injury:'',pregnancy:'not_applicable',medical:false,eatingConcern:false,photo:''};
const defaultState={screen:'landing',step:0,profile:{...DEMO,isDemo:false},plan:null,metrics:null,progress:{workouts:0,habits:0,weights:[]},theme:'premium',presentation:0,playing:false};
let state=loadState();
function loadState(){try{return {...defaultState,...JSON.parse(localStorage.getItem(APP_KEY)||'{}')}}catch(e){return {...defaultState}}}
function save(){try{localStorage.setItem(APP_KEY,JSON.stringify(state))}catch(e){notify('Browser storage is full. Remove the photo or clear old data.')}}
function notify(msg){let n=document.querySelector('.toast');if(!n){n=document.createElement('div');n.className='toast';document.body.appendChild(n)}n.textContent=msg;n.classList.add('show');setTimeout(()=>n.classList.remove('show'),2200)}
function bmi(p){return p.weight/(p.height/100)**2}
function bmr(p){return 10*p.weight+6.25*p.height-5*p.age+(String(p.sex).toLowerCase()==='male'?5:-161)}
function tdee(p){const f={sedentary:1.2,light:1.375,moderate:1.55,high:1.725}[p.activity]||1.2;return bmr(p)*f}
function weeks(p){const d=new Date(p.targetDate);const now=new Date();now.setHours(0,0,0,0);return Math.max(0,Math.ceil((d-now)/604800000))}
function reality(p){const gap=Math.abs(p.target-p.weight),w=weeks(p);if(!w||!gap)return{tone:'warn',label:'NEEDS ADJUSTMENT',rate:0,msg:'Add a future target date and a meaningful target.'};const rate=gap/w;if(rate>1)return{tone:'danger',label:'TIMELINE REQUIRES RECONSIDERATION',rate,msg:`That target implies about ${rate.toFixed(1)} kg/week. Consider a longer timeline; this planner will not encourage extreme restriction or excessive exercise.`};if(rate>.75)return{tone:'warn',label:'NEEDS ADJUSTMENT',rate,msg:`That target implies about ${rate.toFixed(1)} kg/week. A longer timeline may be more practical.`};return{tone:'success',label:'REALISTIC',rate,msg:`That target implies about ${rate.toFixed(1)} kg/week across ${w} weeks. This is planning guidance, not a guarantee.`}}
function safety(p,r){const flags=[];if(['pregnant','postpartum'].includes(p.pregnancy))flags.push(p.pregnancy);if(p.medical)flags.push('medical');if(p.eatingConcern)flags.push('eating');if(String(p.injury||'').trim())flags.push('injury');if(r.tone==='danger')flags.push('extreme_timeline');return flags}
function goalLabel(g){return g==='fatloss'?'Fat loss':g==='muscle'?'Muscle + fitness':'General fitness'}
function filteredFoods(p){const a=String(p.allergies||'').toLowerCase().split(',').map(x=>x.trim()).filter(Boolean),d=String(p.dislikes||'').toLowerCase().split(',').map(x=>x.trim()).filter(Boolean);return FOODS.filter(f=>f.diet.includes(p.diet)).filter(f=>!a.some(x=>f.name.toLowerCase().includes(x))).filter(f=>!d.some(x=>f.name.toLowerCase().includes(x)))}
function makeNutrition(p,r,flags){const blocked=flags.some(x=>['pregnant','postpartum','medical','eating'].includes(x));if(blocked)return{calorie:null,meals:[],warning:'Personalized nutrition targets are limited because a safety concern was flagged. Please seek appropriate professional guidance before making significant changes.'};const pool=filteredFoods(p);const calorie=r.tone==='danger'?null:Math.round(p.goal==='fatloss'?Math.max(tdee(p)-400,tdee(p)*.8):p.goal==='muscle'?tdee(p)+200:tdee(p));const wanted=p.meals>=5?['breakfast','snack','lunch','snack','dinner']:p.meals===3?['breakfast','lunch','dinner']:['breakfast','lunch','snack','dinner'];const out=[];wanted.forEach(slot=>{const c=pool.filter(f=>f.meal.includes(slot)).sort((a,b)=>(b.tags.includes('protein')?2:0)-(a.tags.includes('protein')?2:0)+(a.prep-b.prep<0?1:0));if(c[0])out.push({slot,item:c[0],alts:c.slice(1,3)});});return{calorie,meals:out,warning:r.tone==='danger'?'Timeline is aggressive; no calorie target is prescribed.':''}}
function makeWorkout(p,flags){const blocked=flags.some(x=>['pregnant','postpartum','medical','eating'].includes(x));if(blocked)return{sessions:[],split:'Personalized exercise programming limited',warning:'Personalized exercise programming is limited because a safety concern was flagged. Please seek appropriate professional guidance.'};const mode=p.gym?'gym':'home';const pool=EXERCISES.filter(e=>e.mode.includes(mode)&&e.goal.includes(p.goal)&&e.level.includes(p.level));const patterns=p.goal==='muscle'?['legs','push','pull','hinge','core']:p.goal==='fatloss'?['cardio','legs','push','cardio','core']:['legs','push','pull','core','cardio'];const days=Math.max(2,Math.min(6,Number(p.days)||3));const min=Math.max(15,Math.min(120,Number(p.minutes)||30));const limit=min<=30?3:min<=60?4:6;const sessions=Array.from({length:days},(_,i)=>{let cand=pool.filter(e=>e.pattern===patterns[i%patterns.length]);if(!cand.length)cand=pool;return{day:i+1,focus:(patterns[i%patterns.length]||'full').replace(/^./,x=>x.toUpperCase()),minutes:min,warmup:min<=30?4:min<=60?7:10,exercises:cand.slice(0,limit),cooldown:min<=30?3:min<=60?5:8}});return{sessions,split:p.gym?(p.goal==='muscle'?'Structured resistance split':'Strength + conditioning'):'No-gym walking + bodyweight + mobility',warning:flags.includes('injury')?'You noted an injury or medical concern. Get professional guidance before modifying exercise.':''}}
function roadmap(p,r){const n=Math.min(12,Math.max(4,weeks(p)||8));return Array.from({length:n},(_,i)=>({week:i+1,title:p.goal==='fatloss'?['Build the routine','Protein & portions','Daily movement','Strength consistency'][i%4]:p.goal==='muscle'?['Technique foundation','Progressive overload','Protein consistency','Recovery quality'][i%4]:['Movement baseline','Workout consistency','Food quality','Recovery'][i%4]}))}
function buildPlan(p){const r=reality(p),flags=safety(p,r),n=makeNutrition(p,r,flags),w=makeWorkout(p,flags);return{reality:r,flags,nutrition:n,workout:w,roadmap:roadmap(p,r),habits:[`Sleep ${p.sleep}h`,`${p.steps||7000}+ steps`,`${p.days} workouts/week`,`${p.meals} meals/day`]}}
function journey(){const p=state.profile, entries=state.progress.weights||[];if(!entries.length)return 0;const start=Number(p.weight), latest=Number(entries[entries.length-1].weight),gap=Math.abs(start-Number(p.target));return gap?Math.max(0,Math.min(100,Math.round((Math.abs(start-latest)/gap)*100))):0}
function realityClass(){return state.plan?.reality?.tone||'success'}
function applyTheme(){const t=state.theme||'premium';const map={premium:['#7c5cff','#00d9a6','#07111f'],cinematic:['#ff7a59','#ffd37e','#090b12'],retro:['#ff3cac','#00f5ff','#100c1d'],future:['#48c6ef','#9c8cff','#060b18'],energy:['#c7ff4d','#ff9a3c','#0c1009']};const x=map[t]||map.premium;document.documentElement.style.setProperty('--primary',x[0]);document.documentElement.style.setProperty('--secondary',x[1]);document.documentElement.style.setProperty('--bg',x[2]);document.documentElement.style.setProperty('--grad',`linear-gradient(135deg,${x[0]},${x[1]})`)}
function layout(body,nav=true){return `<div class="app"><header class="topbar"><button class="brand" data-a="home"><span class="mark"><i></i><i></i><i></i></span>MYFIT <span>AI</span></button><div class="top-actions"><button class="icon-btn" data-a="privacy">⌘</button><button class="text-btn" data-a="reset">Reset</button></div></header><main class="main">${body}</main>${nav?`<nav class="bottom"><button data-a="dashboard">⌂ Home</button><button data-a="plan">✦ Plan</button><button data-a="progress">◴ Progress</button><button data-a="privacy">◌ Profile</button></nav>`:''}</div>`}
function render(){applyTheme();let h='';switch(state.screen){case'landing':h=landing();break;case'questionnaire':h=questionnaire();break;case'reality':h=realityScreen();break;case'loading':h=loading();break;case'dashboard':h=dashboard();break;case'plan':h=planScreen();break;case'progress':h=progressScreen();break;case'privacy':h=privacyScreen();break;case'themes':h=themesScreen();break;case'presentation':h=presentation();break;case'report':h=reportPage();break;default:h=landing()}el('app').innerHTML=layout(h,!['landing','loading','presentation'].includes(state.screen));bind();}
function landing(){return `<section class="hero"><div><div class="eyebrow">Personal Wellness & Fitness Planner</div><h1>Your fitness plan.<br><span class="gradient-text">Built around you.</span></h1><p class="lead">MYFIT AI turns your goals, lifestyle, food preferences and available time into an actionable wellness plan — entirely in your browser.</p><div class="actions"><button class="btn btn-primary" data-a="start">Build My Plan →</button><button class="btn btn-secondary" data-a="demo">▶ Explore Demo Mode</button></div><p class="muted" style="font-size:11px;margin-top:20px">No paid AI API · Local planning logic · Optional visual-only photo · Wellness tool, not medical advice.</p></div><div class="preview"><div class="eyebrow">LIVE PREVIEW</div><h3 style="margin-top:10px">Your week at a glance</h3><div class="mini-grid"><div class="mini"><strong>82%</strong><span>Consistency</span></div><div class="mini"><strong>3/4</strong><span>Workouts</span></div><div class="mini"><strong>−2.4kg</strong><span>Trend</span></div><div class="mini"><strong>6 days</strong><span>Streak</span></div></div><div class="notice" style="margin-top:12px"><strong>Today</strong><br><span class="muted">Protein-focused lunch · 30 min movement · recovery habit</span></div></div></section>`}
function questionnaire(){const p=state.profile, s=state.step, total=5;let body='';if(s===0)body=`<div class="grid2"><div class="field"><label>Name / nickname</label><input data-f="name" value="${esc(p.name)}"></div><div class="field"><label>Age</label><input data-f="age" type="number" value="${p.age}"></div><div class="field"><label>Sex</label><select data-f="sex"><option ${p.sex==='Male'?'selected':''}>Male</option><option ${p.sex==='Female'?'selected':''}>Female</option><option ${p.sex==='Other'?'selected':''}>Other</option></select></div><div class="field"><label>Height (cm)</label><input data-f="height" type="number" value="${p.height}"></div><div class="field"><label>Current weight (kg)</label><input data-f="weight" type="number" step="0.1" value="${p.weight}"></div></div>`;else if(s===1)body=`<div class="option-grid">${[['fatloss','🔥 Fat loss','Reduce body weight with a practical routine.'],['muscle','💪 Muscle + fitness','Build strength and improve fitness.'],['fitness','⚡ General fitness','Improve movement, stamina and consistency.']].map(x=>`<button class="option ${p.goal===x[0]?'selected':''}" data-goal="${x[0]}"><strong>${x[1]}</strong><span>${x[2]}</span></button>`).join('')}</div>`;else if(s===2)body=`<div class="grid2"><div class="field"><label>Target weight (kg)</label><input data-f="target" type="number" step="0.1" value="${p.target}"></div><div class="field"><label>Target date</label><input data-f="targetDate" type="date" value="${p.targetDate}"></div><div class="field"><label>Activity level</label><select data-f="activity"><option value="sedentary">Mostly seated</option><option value="light">Lightly active</option><option value="moderate" selected>Moderately active</option><option value="high">Very active</option></select></div><div class="field"><label>Gym access</label><select data-f="gym"><option value="true" ${p.gym?'selected':''}>Gym available</option><option value="false" ${!p.gym?'selected':''}>No gym</option></select></div><div class="field"><label>Days per week</label><input data-f="days" type="number" min="2" max="6" value="${p.days}"></div><div class="field"><label>Minutes / session</label><input data-f="minutes" type="number" min="15" max="120" value="${p.minutes}"></div><div class="field"><label>Training experience</label><select data-f="level"><option value="beginner">Beginner</option><option value="intermediate" ${p.level==='intermediate'?'selected':''}>Intermediate</option><option value="advanced" ${p.level==='advanced'?'selected':''}>Advanced</option></select></div></div>`;else if(s===3)body=`<div class="grid2"><div class="field"><label>Diet style</label><select data-f="diet"><option value="vegetarian">Vegetarian</option><option value="eggetarian">Eggetarian</option><option value="vegan">Vegan</option><option value="non-vegetarian" ${p.diet==='non-vegetarian'?'selected':''}>Non-vegetarian</option><option value="jain">Jain-friendly</option></select></div><div class="field"><label>Cuisine</label><select data-f="cuisine"><option value="mixed">Mixed Indian</option><option value="north-indian">North Indian</option><option value="south-indian">South Indian</option><option value="west-indian">West Indian</option></select></div><div class="field"><label>Meals per day</label><select data-f="meals">${[2,3,4,5].map(n=>`<option value="${n}" ${p.meals===n?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>Cooking availability</label><select data-f="cooking"><option value="limited">Limited — quick meals</option><option value="moderate" selected>Moderate</option><option value="high">Comfortable cooking</option></select></div><div class="field"><label>Budget</label><select data-f="budget"><option value="low">Budget-conscious</option><option value="medium" selected>Moderate</option><option value="flexible">Flexible</option></select></div><div class="field"><label>Workout timing</label><select data-f="workoutTiming"><option value="pre">Before main meal</option><option value="post" selected>After main meal</option><option value="flexible">Flexible</option></select></div><div class="field"><label>Allergies</label><input data-f="allergies" placeholder="e.g. peanuts, dairy" value="${esc(p.allergies)}"></div><div class="field"><label>Foods disliked</label><input data-f="dislikes" placeholder="e.g. fish, paneer" value="${esc(p.dislikes)}"></div><div class="field"><label>Daily steps</label><input data-f="steps" type="number" value="${p.steps}"></div><div class="field"><label>Sleep hours</label><input data-f="sleep" type="number" step="0.5" value="${p.sleep}"></div></div>`;else body=`<div class="grid2"><div class="card safety"><div class="eyebrow">SAFETY CHECK</div><h3 style="margin-top:8px">Flag anything relevant.</h3><div class="field" style="margin-top:15px"><label>Pregnancy / postpartum</label><select data-f="pregnancy"><option value="not_applicable">Not applicable</option><option value="not_pregnant">Not pregnant</option><option value="pregnant">Pregnant</option><option value="postpartum">Postpartum</option></select></div><label class="check-row"><input data-f="medical" type="checkbox" ${p.medical?'checked':''}> Significant medical condition affecting exercise/nutrition</label><label class="check-row"><input data-f="eatingConcern" type="checkbox" ${p.eatingConcern?'checked':''}> Eating-disorder concern / unsafe relationship with food</label><div class="field" style="margin-top:14px"><label>Injury or medical concern</label><textarea data-f="injury" rows="3" placeholder="Optional safety note">${esc(p.injury)}</textarea></div></div><div class="notice safety"><strong>Professional guidance may be needed.</strong><br>Pregnancy/postpartum, significant medical conditions, injuries and eating concerns should be reviewed with an appropriate healthcare professional.</div></div>`;return `<section class="wizard"><div class="wizard-head"><div><div class="eyebrow">Personalization</div><span class="muted">Step ${s+1} of ${total}</span></div><div class="steps">${Array.from({length:total},(_,i)=>`<span class="step ${i<=s?'on':''}"></span>`).join('')}</div></div><div class="card question"><h2>${['Let’s start with you.','What are we working toward?','Make it fit your life.','Finish your preferences.','One important safety check.'][s]}</h2><p class="muted">${['A few core details help MYFIT AI personalize your plan.','Your goal changes what the recommendation engine prioritizes.','Answer only what matters for your chosen goal.','We use these to filter practical recommendations.','These answers change what MYFIT AI is allowed to recommend.'][s]}</p>${body}<div class="wizard-actions"><button class="btn btn-secondary" data-a="prev" ${s===0?'disabled':''}>← Back</button><button class="btn btn-primary" data-a="next">${s===total-1?'Build my plan':'Continue →'}</button></div></div></section>`}
function metricsBlock(){const p=state.profile;state.metrics={bmi:bmi(p),bmr:bmr(p),tdee:tdee(p),reality:reality(p)}}
function realityScreen(){const p=state.profile,m=state.metrics,r=m.reality,scale=Math.min(100,Math.max(8,r.rate/1.2*100));return `<section><div class="eyebrow">Reality Check</div><h2 style="margin-top:7px">Your target, honestly assessed.</h2><div class="reality" style="margin-top:18px"><div class="card"><span class="status ${r.tone}">${r.label}</span><div class="big-number">${p.weight} → ${p.target} kg</div><p class="muted">${Math.abs(p.target-p.weight).toFixed(1)} kg target gap · ${m.reality.weeks||weeks(p)} weeks</p><div class="scale"><i style="left:${scale}%"></i></div></div><div class="card"><h3>${r.label}</h3><p class="muted">${esc(r.msg)}</p><div class="notice safety">BMI ${m.bmi.toFixed(1)} · ${m.bmi<18.5?'Below typical range':m.bmi<25?'Typical range':m.bmi<30?'Above typical range':'High range'}. BMI is a screening measure, not a diagnosis.</div>${state.plan.flags.length?`<div class="notice danger" style="margin-top:10px"><strong>Safety guidance</strong><br>${state.plan.nutrition.warning||state.plan.workout.warning||'Professional guidance is recommended.'}</div>`:''}</div></div><div class="actions" style="justify-content:flex-end"><button class="btn btn-primary" data-a="generate">Build my personalized plan →</button></div></section>`}
function loading(){return `<section class="loading"><div><div class="orb"></div><div class="eyebrow" style="margin-top:20px">MYFIT AI ENGINE</div><h2>Building your plan.</h2><p class="muted">Everything is generated locally — no paid AI API.</p></div></section>`}
function dashboard(){const p=state.profile,m=state.metrics,pl=state.plan,j=journey(),r=m.reality;const meal=pl.nutrition.meals[0],sess=pl.workout.sessions[0];return `<section class="dashboard"><div class="dash-hero"><div><div class="eyebrow">MY JOURNEY</div><h2>${esc(p.name||'Your')}, this is your plan in motion.</h2><p class="muted">${esc(goalLabel(p.goal))} · ${p.days} days/week · ${m.reality.weeks||'—'} weeks</p><span class="status ${r.tone}">${r.label}</span></div><div class="journey-ring" style="--p:${j}"><div><strong>${j}%</strong><span>journey</span></div></div></div><div class="kpis"><div class="card kpi"><span class="label">CURRENT</span><strong>${p.weight} kg</strong><span class="muted">Baseline</span></div><div class="card kpi"><span class="label">TARGET</span><strong>${p.target} kg</strong><span class="muted">${Math.abs(p.target-p.weight).toFixed(1)} kg gap</span></div><div class="card kpi"><span class="label">BMI</span><strong>${m.bmi.toFixed(1)}</strong><span class="muted">Screening measure</span></div><div class="card kpi"><span class="label">TDEE</span><strong>${Math.round(m.tdee)}</strong><span class="muted">Planning estimate</span></div></div><div class="dash-grid"><div class="card"><div class="eyebrow">REALITY CHECK</div><h3 style="margin-top:8px">${r.tone==='success'?'🟢':r.tone==='warn'?'🟡':'🔴'} ${r.label}</h3><p class="muted">${esc(r.msg)}</p></div><div class="card"><div class="eyebrow">TODAY</div><h3 style="margin-top:8px">${esc(meal?.item?.name||'Your meal')}</h3><p class="muted">${esc(meal?.item?.portion||'Follow your planned meal rhythm.')}</p><button class="text-btn" data-a="plan">Open plan</button></div></div><div class="section-title"><div><div class="eyebrow">WEEKLY ROADMAP</div><h3>Next milestones</h3></div><button class="text-btn" data-a="presentation">Presentation Mode</button></div><div class="card"><div class="roadmap-track">${pl.roadmap.slice(0,8).map((w,i)=>`<button class="roadmap-node ${i===0?'current':''}"><b>${w.week}</b><span>${esc(w.title)}</span></button>`).join('')}</div></div><div class="section-title"><div><div class="eyebrow">KEY HABITS</div><h3>Only what matters most</h3></div></div><div class="habits">${pl.habits.map(h=>`<div class="habit"><b>${esc(h)}</b><small>Keep this simple and repeatable.</small></div>`).join('')}</div><div class="photo-panel">${p.photo?`<img class="photo-preview" src="${p.photo}" alt="Optional personal photo">`:`<div class="photo-empty">Optional visual personalization.<br>No medical or body measurement analysis.</div>`}<div><div class="eyebrow">VISUAL PERSONALIZATION</div><h3>${p.photo?'Your photo is stored locally.':'Add a personal touch.'}</h3><p class="muted">The photo is not analyzed for BMI, body fat, obesity or medical conditions.</p><div class="photo-actions"><button class="btn btn-secondary btn-sm" data-a="photo">${p.photo?'Change photo':'Add photo'}</button>${p.photo?'<button class="text-btn" data-a="delete-photo">Delete photo</button>':''}</div></div></div><div class="actions"><button class="btn btn-primary" data-a="report">Download My Plan</button><button class="btn btn-secondary" data-a="themes">Themes</button></div></section>`}
function planScreen(){const p=state.profile,pl=state.plan;return `<section><div class="eyebrow">PERSONALIZED PLAN</div><h2 style="margin-top:7px">Built for your routine.</h2><div class="plan-grid" style="margin-top:18px"><div class="card"><div class="eyebrow">NUTRITION</div><h3 style="margin-top:8px">Indian meal structure</h3>${pl.nutrition.calorie?`<p class="muted">Planning target: ${pl.nutrition.calorie} kcal/day</p>`:'<div class="notice safety">No calorie target provided because the safety/timeline rules call for professional guidance.</div>'}<div class="list" style="margin-top:12px">${pl.nutrition.meals.length?pl.nutrition.meals.map(m=>`<div class="list-item"><strong>${esc(m.slot)} · ${esc(m.item.name)}</strong><small>${esc(m.item.portion)}</small><small>Alternatives: ${(m.alts||[]).map(x=>esc(x.name)).join(' · ')||'—'}</small></div>`).join(''):`<div class="notice danger">${esc(pl.nutrition.warning)}</div>`}</div></div><div class="card"><div class="eyebrow">WORKOUT</div><h3 style="margin-top:8px">${esc(pl.workout.split)}</h3><div class="list" style="margin-top:12px">${pl.workout.sessions.length?pl.workout.sessions.map(s=>`<div class="list-item"><strong>Day ${s.day} · ${esc(s.focus)} · ${s.minutes} min</strong><small>Warm-up ${s.warmup} min · ${(s.exercises||[]).map(e=>`${esc(e.name)} — ${e.sets}×${esc(e.reps)}`).join(' · ')}</small><small>Cool-down ${s.cooldown} min</small></div>`).join(''):`<div class="notice danger">${esc(pl.workout.warning)}</div>`}</div></div></div></section>`}
function progressScreen(){const e=state.progress.weights||[],p=state.profile,cur=e.length?e[e.length-1].weight:p.weight;return `<section><div class="eyebrow">PROGRESS</div><h2 style="margin-top:7px">Measure momentum, not perfection.</h2><div class="kpis" style="margin-top:18px"><div class="card kpi"><span class="label">LATEST</span><strong>${Number(cur).toFixed(1)} kg</strong></div><div class="card kpi"><span class="label">WORKOUTS</span><strong>${state.progress.workouts}</strong><button class="text-btn" data-a="log-workout">Log workout</button></div><div class="card kpi"><span class="label">HABITS</span><strong>${state.progress.habits}</strong><button class="text-btn" data-a="log-habit">Log habit</button></div><div class="card kpi"><span class="label">WEIGHTS</span><strong>${e.length}</strong><button class="text-btn" data-a="log-weight">Log weight</button></div></div><div class="card" style="margin-top:14px"><div class="eyebrow">WEIGHT TREND</div>${e.length?`<div class="progress-chart">${e.slice(-14).map(x=>`<div class="bar" title="${x.date}: ${x.weight} kg" style="height:${Math.max(10,Math.min(100,(Number(x.weight)/(Math.max(...e.map(a=>a.weight),1)))*100))}%"></div>`).join('')}</div>`:'<div class="notice" style="margin-top:12px">No weight entries yet. Add your first entry to start the local trend.</div>'}</div></section>`}
function privacyScreen(){return `<section><div class="eyebrow">PRIVACY & SAFETY</div><h2 style="margin-top:7px">You control your data.</h2><div class="grid2" style="margin-top:18px"><div class="card"><h3>Browser-local data</h3><p class="muted">This version stores profile, plan and progress in this browser's local storage. The application does not send that data to a MYFIT AI backend. Browser/OS backup and extension behavior are outside the application's control.</p><button class="btn btn-danger" data-a="delete-data">Delete My Data</button></div><div class="card safety"><h3>Safety</h3><p class="muted">MYFIT AI is a wellness planning tool, not a diagnosis or treatment tool. Pregnancy/postpartum, significant medical conditions, significant injuries and eating concerns may limit personalized recommendations.</p></div></div></section>`}
function themesScreen(){const t=[['premium','Premium','#7c5cff','#00d9a6','#07111f'],['cinematic','Cinematic','#ff7a59','#ffd37e','#090b12'],['retro','Retro','#ff3cac','#00f5ff','#100c1d'],['future','Future','#48c6ef','#9c8cff','#060b18'],['energy','Energy','#c7ff4d','#ff9a3c','#0c1009']];return `<section><div class="eyebrow">THEME STUDIO</div><h2 style="margin-top:7px">Change the atmosphere.</h2><div class="theme-grid" style="margin-top:18px">${t.map(x=>`<button class="theme ${state.theme===x[0]?'selected':''}" data-theme="${x[0]}" style="--a:${x[2]};--b:${x[3]};--c:${x[4]}"><div class="swatch"><div>${x[1]}</div></div><div class="theme-name"><b>${x[1]}</b><span>Original MYFIT visual treatment</span></div></button>`).join('')}</div></section>`}
function presentation(){const p=state.profile,m=state.metrics,pl=state.plan,i=state.presentation,slides=[
()=>`<div class="eyebrow">01 · USER PROFILE</div><h1>Meet ${esc(p.name||'the person behind the plan')}.</h1><p>${esc(p.age)} years · ${esc(p.sex)} · ${esc(p.diet)} · ${p.gym?'Gym':'No gym'}</p><div class="pres-grid"><div class="pres-cell"><span class="eyebrow">GOAL</span><strong>${goalLabel(p.goal)}</strong></div><div class="pres-cell"><span class="eyebrow">DAYS</span><strong>${p.days}/wk</strong></div><div class="pres-cell"><span class="eyebrow">TIME</span><strong>${p.minutes}m</strong></div><div class="pres-cell"><span class="eyebrow">MEALS</span><strong>${p.meals}/day</strong></div></div>`,
()=>`<div class="eyebrow">02 · CURRENT SITUATION</div><h1>${p.weight} kg</h1><p>Height ${p.height} cm · BMI ${m.bmi.toFixed(1)} · ${p.sleep}h sleep target</p>`,
()=>`<div class="eyebrow">03 · GOAL</div><h1>${goalLabel(p.goal)}</h1><p>${p.weight} kg <span class="gradient-text">→</span> ${p.target} kg · ${m.reality.weeks||'—'} weeks</p>`,
()=>`<div class="eyebrow">04 · REALITY CHECK</div><span class="status ${m.reality.tone}">${m.reality.label}</span><h1>${m.reality.rate.toFixed(1)} kg/week</h1><p>${esc(m.reality.msg)}</p>`,
()=>`<div class="eyebrow">05 · NUTRITION</div><h1>Food that fits your life.</h1><p>${esc(pl.nutrition.meals[0]?.item?.name||'Personalized Indian meals')} · ${esc(pl.nutrition.meals[0]?.item?.portion||'Practical portion')}</p>`,
()=>`<div class="eyebrow">06 · WORKOUT</div><h1>${esc(pl.workout.sessions[0]?.focus||'Movement')}</h1><p>${p.minutes} minutes · ${p.gym?'Gym-based':'No gym'} · ${pl.workout.sessions[0]?.exercises?.map(e=>esc(e.name)).join(' · ')||'Safety-guided plan'}</p>`,
()=>`<div class="eyebrow">07 · WEEKLY ROADMAP</div><h1>Small milestones.</h1><div class="pres-grid">${pl.roadmap.slice(0,4).map(w=>`<div class="pres-cell"><span class="eyebrow">WEEK ${w.week}</span><strong>${esc(w.title)}</strong></div>`).join('')}</div>`,
()=>`<div class="eyebrow">08 · HABITS</div><h1>Keep the promise small.</h1><div class="pres-grid">${pl.habits.map(h=>`<div class="pres-cell"><strong>${esc(h)}</strong></div>`).join('')}</div>`,
()=>`<div class="eyebrow">09 · PROGRESS</div><h1>${journey()}%</h1><p>journey progress · ${state.progress.weights.length} weight entries · ${state.progress.workouts} workouts · ${state.progress.habits} habit check-ins</p>`,
()=>`<div><div class="final-quote">YOUR PLAN IS NOT A PUNISHMENT.</div><div class="final-quote accent">IT'S A SYSTEM YOU CAN ACTUALLY LIVE WITH.</div><p style="margin-top:22px">MYFIT AI · Built around you.</p></div>`];return `<section class="presentation"><div class="present-top"><span class="eyebrow">MYFIT AI · PRESENTATION MODE · ${i+1}/10</span><button class="btn btn-secondary btn-sm" data-a="exit-presentation">Exit</button></div><div class="present-progress"><span style="width:${((i+1)/10)*100}%"></span></div><div class="present-slide">${slides[i]()}</div><div class="present-controls"><button class="btn btn-secondary" data-a="prev-pres" ${i===0?'disabled':''}>← Previous</button><button class="btn btn-primary" data-a="play-pres">${state.playing?'Pause':'Play'}</button><button class="btn btn-secondary" data-a="next-pres" ${i===9?'disabled':''}>Next →</button></div></section>`}
function reportData(){
  const p=state.profile,m=state.metrics,pl=state.plan||{};
  const entries=state.progress?.weights||[];
  const goalGap=Math.abs(Number(p.weight||0)-Number(p.target||0));
  const latest=Number((entries[entries.length-1]||{}).weight||p.weight||0);
  const totalGap=Math.max(goalGap,0.1);
  const progress=Math.max(0,Math.min(100,Math.round(((goalGap-Math.abs(latest-Number(p.target||0)))/totalGap)*100)));
  const realityTone=m.reality?.tone||'success';
  const realityColor=realityTone==='danger'?'#ef4444':realityTone==='warn'?'#f59e0b':'#10b981';
  const realityLabel=m.reality?.label||'REALISTIC';
  const mealCards=(pl.nutrition?.meals||[]).map(x=>`<article class="meal-card"><div class="meal-slot">${esc(x.slot)}</div><h3>${esc(x.item?.name||'')}</h3><p>${esc(x.item?.portion||'')}</p><div class="tags">${(x.item?.tags||[]).map(t=>`<span>${esc(t)}</span>`).join('')}</div></article>`).join('');
  const workoutCards=(pl.workout?.sessions||[]).map(s=>`<article class="workout-card"><div class="workout-top"><strong>${esc(s.day||'')}</strong><span>${esc(s.focus||'')}</span><em>${String(s.duration||'')} min</em></div><div class="exercise-list">${(s.exercises||[]).map(e=>`<div><b>${esc(e.name||'')}</b><span>${String(e.sets||'')} × ${esc(e.reps||'')}</span></div>`).join('')}</div></article>`).join('');
  const roadmap=(pl.roadmap||[]).map((w,i)=>`<div class="road-node ${i===0?'active':''}"><div class="road-dot">${String(w.week||i+1)}</div><div><b>Week ${String(w.week||i+1)}</b><strong>${esc(w.title||'')}</strong><p>${esc(w.target||w.highlight||'')}</p></div></div>`).join('');
  const habits=(pl.habits||[]).map((h,i)=>`<div class="habit-item"><span>${String(i+1).padStart(2,'0')}</span><b>${esc(h)}</b></div>`).join('');
  let trend='';
  if(entries.length){
    const vals=entries.slice(-8).map(x=>Number(x.weight)).filter(Number.isFinite);
    const min=Math.min(...vals,Number(p.target||0)); const max=Math.max(...vals,Number(p.target||0)); const rg=Math.max(1,max-min);
    const pts=vals.map((v,i)=>{const x=8+(i*(84/Math.max(1,vals.length-1))); const y=88-((v-min)/rg)*68; return `${x.toFixed(1)},${y.toFixed(1)}`}).join(' ');
    trend=`<svg viewBox="0 0 100 100" preserveAspectRatio="none" class="trend"><defs><linearGradient id="g" x1="0" x2="1"><stop offset="0" stop-color="#7c5cff"/><stop offset="1" stop-color="#00d9a6"/></linearGradient></defs><line x1="6" y1="88" x2="94" y2="88" stroke="#d7dee9" stroke-width="1"/><polyline points="${pts}" fill="none" stroke="url(#g)" stroke-width="3" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
  } else trend='<div class="empty-trend"><b>No progress entries yet</b><span>Log a weight in MYFIT AI to reveal your local trend.</span></div>';
  const circumference=2*Math.PI*42; const dash=(circumference*progress/100).toFixed(1);
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MYFIT AI - Personal Wellness Plan</title><style>
@page{size:A4;margin:10mm}*{box-sizing:border-box}html,body{margin:0;padding:0}body{font-family:Inter,Arial,sans-serif;color:#152238;background:#fff;line-height:1.45;-webkit-print-color-adjust:exact;print-color-adjust:exact}.page{padding:3mm 0;break-after:page}.page:last-child{break-after:auto}.cover{min-height:260mm;border-radius:28px;padding:28px;background:radial-gradient(circle at 85% 10%,rgba(124,92,255,.2),transparent 25%),radial-gradient(circle at 15% 85%,rgba(0,217,166,.14),transparent 24%),linear-gradient(145deg,#0a1322,#13233a);color:#fff;position:relative;overflow:hidden}.cover:after{content:"";position:absolute;inset:auto -10% -18% 45%;height:210px;background:linear-gradient(90deg,#7c5cff,#00d9a6);filter:blur(55px);opacity:.18}.brand{letter-spacing:.18em;font-size:11px;font-weight:800;color:#66edd1}.cover h1{font-size:44px;line-height:1;letter-spacing:-.05em;margin:16px 0 12px;max-width:540px}.cover p{color:#c8d1df;max-width:520px;font-size:13px}.cover-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:28px}.cover-kpi{padding:14px;border-radius:16px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.12)}.cover-kpi span{display:block;font-size:8px;letter-spacing:.14em;color:#9faabd}.cover-kpi strong{display:block;font-size:20px;margin-top:4px}.cover-footer{position:absolute;left:28px;right:28px;bottom:24px;display:flex;justify-content:space-between;color:#9faabd;font-size:9px}.section-title{font-size:25px;letter-spacing:-.03em;margin:0 0 13px}.eyebrow{font-size:9px;letter-spacing:.18em;color:#6b54dd;font-weight:800}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:12px}.panel{border:1px solid #dce3ec;border-radius:18px;padding:16px;background:#fff;break-inside:avoid;box-shadow:0 4px 18px rgba(20,32,56,.04)}.metric{min-height:112px}.metric span{display:block;color:#6e7a8d;font-size:9px;text-transform:uppercase;letter-spacing:.1em}.metric strong{display:block;font-size:28px;margin-top:9px;letter-spacing:-.04em}.metric small{color:#6e7a8d}.reality-panel{display:grid;grid-template-columns:135px 1fr;gap:22px;align-items:center}.reality-ring{width:130px;height:130px}.ring-bg{fill:none;stroke:#e7ebf0;stroke-width:10}.ring-val{fill:none;stroke:var(--reality);stroke-width:10;stroke-linecap:round;transform:rotate(-90deg);transform-origin:50% 50%}.reality-copy b{display:inline-block;padding:6px 10px;border-radius:999px;background:#eefaf6;color:var(--reality);font-size:10px;letter-spacing:.09em}.reality-copy h3{margin:10px 0 4px;font-size:21px}.reality-copy p{font-size:11px;color:#637084;margin:0}.bar{height:10px;background:#edf1f5;border-radius:999px;overflow:hidden;margin-top:12px}.bar span{display:block;height:100%;width:${progress}%;background:linear-gradient(90deg,#7c5cff,#00d9a6)}.section{margin-top:18px}.meal-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.meal-card{padding:14px;border:1px solid #dce3ec;border-radius:16px;background:linear-gradient(145deg,#fff,#f8fafc);break-inside:avoid}.meal-slot{font-size:8px;letter-spacing:.16em;color:#00a788;font-weight:800;text-transform:uppercase}.meal-card h3{font-size:14px;margin:8px 0 4px}.meal-card p{font-size:10px;color:#667386;margin:0;min-height:28px}.tags{margin-top:9px;display:flex;gap:5px;flex-wrap:wrap}.tags span{font-size:8px;border-radius:99px;background:#eef2ff;color:#5a43c6;padding:4px 6px}.workout-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.workout-card{border:1px solid #dce3ec;border-radius:16px;padding:14px;break-inside:avoid}.workout-top{display:grid;grid-template-columns:45px 1fr auto;gap:8px;align-items:center;border-bottom:1px solid #e9edf2;padding-bottom:9px}.workout-top strong{font-size:14px}.workout-top span{font-size:10px;color:#667386}.workout-top em{font-style:normal;font-size:9px;color:#5a43c6}.exercise-list>div{display:flex;justify-content:space-between;gap:10px;padding:7px 0;border-bottom:1px dashed #e4e8ee;font-size:9px}.exercise-list>div:last-child{border-bottom:0}.exercise-list span{color:#667386}.roadmap{padding:16px}.road-node{display:grid;grid-template-columns:30px 1fr;gap:11px;padding:10px 0;border-bottom:1px solid #edf0f4;position:relative}.road-node:last-child{border-bottom:0}.road-dot{width:26px;height:26px;border-radius:50%;background:#eff2ff;color:#5a43c6;display:grid;place-items:center;font-size:9px;font-weight:800;border:1px solid #d8ddf7}.road-node.active .road-dot{background:linear-gradient(135deg,#7c5cff,#00d9a6);color:#fff;border-color:transparent}.road-node b{font-size:8px;letter-spacing:.14em;color:#8792a3;text-transform:uppercase}.road-node strong{display:block;font-size:12px;margin:2px 0}.road-node p{font-size:9px;color:#667386;margin:0}.habit-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.habit-item{display:flex;gap:10px;align-items:center;padding:13px;border:1px solid #dce3ec;border-radius:15px}.habit-item span{width:28px;height:28px;border-radius:9px;background:#eef2ff;color:#5a43c6;display:grid;place-items:center;font-size:9px;font-weight:800}.habit-item b{font-size:11px}.trend-panel{padding:16px;border:1px solid #dce3ec;border-radius:18px}.trend-wrap{height:190px;background:repeating-linear-gradient(to bottom,#fff 0,#fff 44px,#f0f3f7 45px);border-radius:13px;overflow:hidden}.trend{width:100%;height:100%}.empty-trend{height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#667386;font-size:10px;text-align:center;gap:5px}.empty-trend b{color:#152238}.quote{font-size:25px;font-weight:900;letter-spacing:-.04em;line-height:1.02;margin-top:22px}.quote.accent{color:#5a43c6}.disclaimer{font-size:9px;color:#667386}.footer{border-top:1px solid #e4e8ef;padding-top:10px;margin-top:20px;color:#8993a3;font-size:8px;display:flex;justify-content:space-between}.no-print{margin-top:16px}@media print{.no-print{display:none}}
</style></head><body>
<div class="page"><section class="cover"><div class="brand">MYFIT AI · PERSONAL WELLNESS & FITNESS PLANNER</div><h1>Your plan, designed around your life.</h1><p>Local wellness planning with practical Indian-focused nutrition, adaptive movement and a realistic weekly roadmap.</p><div class="cover-grid"><div class="cover-kpi"><span>Current</span><strong>${esc(p.weight)} kg</strong></div><div class="cover-kpi"><span>Target</span><strong>${esc(p.target)} kg</strong></div><div class="cover-kpi"><span>BMI</span><strong>${Number(m.bmi).toFixed(1)}</strong></div><div class="cover-kpi"><span>Timeline</span><strong>${String(m.reality?.weeks||'—')} wks</strong></div></div><svg style="position:absolute;right:40px;bottom:72px;width:180px;height:180px" viewBox="0 0 110 110" class="reality-ring"><circle class="ring-bg" cx="55" cy="55" r="42"/><circle class="ring-val" cx="55" cy="55" r="42" style="--reality:${realityColor};stroke-dasharray:${dash} ${circumference.toFixed(1)}"/><text x="55" y="52" text-anchor="middle" font-size="18" font-weight="800" fill="#fff">${progress}%</text><text x="55" y="64" text-anchor="middle" font-size="7" fill="#c8d1df">JOURNEY</text></svg><div class="cover-footer"><span>${esc(p.name||'MYFIT User')} · ${esc(goalLabel(p.goal))}</span><span>Generated locally</span></div></section></div>
<div class="page"><div class="eyebrow">01 · YOUR BASELINE</div><h2 class="section-title">Profile & Reality Check</h2><div class="grid2"><div class="panel metric"><span>Height</span><strong>${esc(p.height)} cm</strong><small>${esc(p.activity)} activity</small></div><div class="panel metric"><span>Weight</span><strong>${esc(p.weight)} → ${esc(p.target)} kg</strong><small>${goalGap.toFixed(1)} kg planned change</small></div><div class="panel metric"><span>BMR</span><strong>${Math.round(m.bmr)}</strong><small>estimated kcal/day</small></div><div class="panel metric"><span>TDEE</span><strong>${Math.round(m.tdee)}</strong><small>estimated kcal/day</small></div></div><div class="section"><div class="panel reality-panel" style="--reality:${realityColor}"><svg class="reality-ring" viewBox="0 0 110 110"><circle class="ring-bg" cx="55" cy="55" r="42"/><circle class="ring-val" cx="55" cy="55" r="42" style="stroke-dasharray:${dash} ${circumference.toFixed(1)}"/><text x="55" y="52" text-anchor="middle" font-size="15" font-weight="800" fill="#152238">${progress}%</text><text x="55" y="64" text-anchor="middle" font-size="7" fill="#667386">JOURNEY</text></svg><div class="reality-copy"><b>${esc(realityLabel)}</b><h3>${esc(String(m.reality?.rate||'—'))} kg/week planning rate</h3><p>${esc(m.reality?.msg||'')}</p><div class="bar"><span></span></div><p style="margin-top:7px">BMI ${Number(m.bmi).toFixed(1)} · BMI is a screening measure, not a diagnosis.</p></div></div></div><div class="section"><div class="panel"><div class="eyebrow">WHY THIS PLAN</div><p style="font-size:11px;color:#637084;margin:7px 0 0">Goal: <b>${esc(goalLabel(p.goal))}</b> · ${esc(p.dietType)} · ${p.gym?'Gym':'No gym'} · ${esc(p.days)} days/week · ${esc(p.minutes)} min/session · ${esc(p.meals)} meals/day.</p></div></div></div>
<div class="page"><div class="eyebrow">02 · FUEL</div><h2 class="section-title">Nutrition that fits your day</h2><div class="meal-grid">${mealCards}</div><div class="section"><div class="panel"><div class="eyebrow">PLANNING NOTE</div><p class="disclaimer">Meals are practical planning examples filtered to the selected diet style. They are not a medical diet or a guaranteed calorie prescription.</p></div></div><div class="section"><div class="eyebrow">03 · MOVE</div><h2 class="section-title">Adaptive workout plan</h2><div class="workout-grid">${workoutCards}</div></div></div>
<div class="page"><div class="eyebrow">04 · ROADMAP</div><h2 class="section-title">From goal to weekly milestones</h2><div class="panel roadmap">${roadmap}</div><div class="section"><div class="eyebrow">05 · HABITS</div><h2 class="section-title">The small promises</h2><div class="habit-grid">${habits}</div></div><div class="section trend-panel"><div class="eyebrow">06 · PROGRESS</div><h2 class="section-title" style="margin-bottom:8px">Your local trend</h2><div class="trend-wrap">${trend}</div><p class="disclaimer" style="margin-top:8px">Progress data is stored locally in this browser in the current MYFIT AI architecture.</p></div></div>
<div class="page"><div class="eyebrow">07 · SAFETY</div><h2 class="section-title">Wellness, not medical treatment</h2><div class="panel"><p class="disclaimer">MYFIT AI is a wellness and fitness planning tool. It is not a medical diagnosis or treatment tool and does not replace a doctor or registered dietitian. BMI, BMR, TDEE and timeline outputs are estimates. Optional photos are for visual personalization only and are not analyzed for body measurements or medical conditions.</p></div><div class="quote">YOUR PLAN IS NOT A PUNISHMENT.</div><div class="quote accent">IT'S A SYSTEM YOU CAN ACTUALLY LIVE WITH.</div><div class="footer"><span>MYFIT AI</span><span>Generated locally in your browser</span></div><div class="no-print"><button onclick="window.print()" style="padding:11px 16px;border:0;border-radius:10px;background:linear-gradient(135deg,#7c5cff,#00d9a6);color:#fff;font-weight:800">Save / Print as PDF</button></div></div></body></html>`;
}
function reportPage(){return `<section class="report-page"><div class="eyebrow">REPORT</div><h2 style="margin-top:7px">Your plan is ready.</h2><p class="muted">Use the button below to open the browser's native print-to-PDF flow.</p><div class="card"><button class="btn btn-primary" data-a="print-report">Download / Save PDF</button></div></section>`}
let timer=null;
function startTimer(){stopTimer();timer=setInterval(()=>{if(state.screen==='presentation'&&state.playing){if(state.presentation<9){state.presentation++;render()}else{state.playing=false;stopTimer();render()}}},5000)}
function stopTimer(){if(timer){clearInterval(timer);timer=null}}
function openReport(){
  const frame=document.createElement('iframe');
  frame.setAttribute('aria-hidden','true');
  frame.style.position='fixed';
  frame.style.width='0';
  frame.style.height='0';
  frame.style.border='0';
  frame.style.opacity='0';
  frame.style.pointerEvents='none';
  document.body.appendChild(frame);
  frame.srcdoc=reportData();
  frame.onload=()=>{
    setTimeout(()=>{
      try{
        frame.contentWindow.focus();
        frame.contentWindow.print();
      }catch(e){
        notify('Your browser blocked the print window. Use Ctrl+P to save the report as PDF.');
      }
      setTimeout(()=>frame.remove(),1500);
    },250);
  };
}
function bind(){document.querySelectorAll('[data-a]').forEach(b=>b.addEventListener('click',()=>act(b.dataset.a)));document.querySelectorAll('[data-goal]').forEach(b=>b.addEventListener('click',()=>{state.profile.goal=b.dataset.goal;save();render()}));document.querySelectorAll('[data-theme]').forEach(b=>b.addEventListener('click',()=>{state.theme=b.dataset.theme;save();render()}));document.querySelectorAll('[data-f]').forEach(x=>x.addEventListener(x.type==='checkbox'?'change':'input',()=>{const k=x.dataset.f;let v=x.type==='checkbox'?x.checked:x.value;if(['age','height','weight','target','days','minutes','meals','steps','sleep'].includes(k))v=Number(v);if(k==='gym')v=v==='true';state.profile[k]=v;save()}));}
function act(a){if(a==='home'){state.screen='landing';render();return}if(a==='start'){state.profile={...DEMO,isDemo:false,name:'',age:34};state.step=0;state.screen='questionnaire';render();return}if(a==='demo'){state.profile={...DEMO,isDemo:true};state.metrics={bmi:bmi(state.profile),bmr:bmr(state.profile),tdee:tdee(state.profile),reality:reality(state.profile)};state.plan=buildPlan(state.profile);state.screen='reality';save();render();return}if(a==='prev'){state.step=Math.max(0,state.step-1);render();return}if(a==='next'){if(state.step<4){state.step++;render()}else{metricsBlock();state.plan=buildPlan(state.profile);state.screen='reality';save();render()}return}if(a==='generate'){metricsBlock();state.plan=buildPlan(state.profile);state.screen='loading';save();render();setTimeout(()=>{state.screen='dashboard';render()},700);return}if(a==='dashboard'){if(!state.plan){state.screen='landing'}else state.screen='dashboard';render();return}if(a==='plan'){state.screen='plan';render();return}if(a==='progress'){state.screen='progress';render();return}if(a==='privacy'){state.screen='privacy';render();return}if(a==='themes'){state.screen='themes';render();return}if(a==='presentation'){state.presentation=0;state.playing=false;state.screen='presentation';startTimer();render();return}if(a==='exit-presentation'){stopTimer();state.playing=false;state.screen='dashboard';render();return}if(a==='prev-pres'){state.presentation=Math.max(0,state.presentation-1);render();return}if(a==='next-pres'){state.presentation=Math.min(9,state.presentation+1);render();return}if(a==='play-pres'){state.playing=!state.playing;if(state.playing)startTimer();else stopTimer();render();return}if(a==='progress'){state.screen='progress';render();return}if(a==='log-workout'){state.progress.workouts++;save();notify('Workout logged.');render();return}if(a==='log-habit'){state.progress.habits++;save();notify('Habit logged.');render();return}if(a==='log-weight'){const w=Number(prompt('Enter weight in kg'));if(w>0){state.profile.weight=w;state.progress.weights.push({date:new Date().toISOString().slice(0,10),weight:w});metricsBlock();state.plan=buildPlan(state.profile);save();render()}return}if(a==='photo'){const input=document.createElement('input');input.type='file';input.accept='image/*';input.onchange=()=>{const f=input.files&&input.files[0];if(!f)return;if(f.size>1500000){notify('Choose a photo under 1.5 MB.');return}const r=new FileReader();r.onload=()=>{state.profile.photo=r.result;save();render()};r.readAsDataURL(f)};input.click();return}if(a==='delete-photo'){state.profile.photo='';save();render();notify('Photo deleted.');return}if(a==='delete-data'){if(confirm('Delete all MYFIT AI data stored in this browser?')){localStorage.removeItem(APP_KEY);state={...defaultState,profile:{...DEMO,isDemo:false},progress:{workouts:0,habits:0,weights:[]}};applyTheme();render();notify('Data deleted.')}}if(a==='report'){state.screen='report';render();return}if(a==='print-report'){openReport();return}if(a==='reset'){if(confirm('Reset MYFIT AI in this browser?')){localStorage.removeItem(APP_KEY);state={...defaultState,profile:{...DEMO,isDemo:false},progress:{workouts:0,habits:0,weights:[]}};render();notify('Reset complete.')}}}

document.addEventListener('keydown',e=>{if(state.screen!=='presentation')return;if(e.key==='ArrowRight')act('next-pres');if(e.key==='ArrowLeft')act('prev-pres');if(e.key===' '){e.preventDefault();act('play-pres')}if(e.key==='Escape')act('exit-presentation')});

render();
})();
